import { precacheAndRoute } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { CacheFirst, StaleWhileRevalidate } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';

// serviceWorkerRegistration.ts posts SKIP_WAITING when a new version is
// waiting, so a deploy takes effect without closing every tab.
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

// Precache all assets generated by the build process
// eslint-disable-next-line no-restricted-globals
precacheAndRoute(self.__WB_MANIFEST);

// Cache images aggressively with CacheFirst strategy
// Images are static and don't change, so cache them for a long time
registerRoute(
  ({request}) => request.destination === 'image',
  new CacheFirst({
    cacheName: 'images',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 2000,
        maxAgeSeconds: 30 * 24 * 60 * 60, // 30 days
      }),
    ],
  })
);

// Cache API calls with stale-while-revalidate
// This provides fast responses while keeping data fresh
registerRoute(
  ({url}) => url.pathname.startsWith('/api'),
  new StaleWhileRevalidate({
    cacheName: 'api-cache',
  })
);

// Cache JSON data files (like data.json) with stale-while-revalidate
registerRoute(
  ({url}) => url.pathname.endsWith('.json'),
  new StaleWhileRevalidate({
    cacheName: 'data-cache',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 50,
        maxAgeSeconds: 24 * 60 * 60, // 24 hours
      }),
    ],
  })
);

// Cache fonts with CacheFirst strategy
registerRoute(
  ({url}) => url.pathname.includes('/fonts/'),
  new CacheFirst({
    cacheName: 'fonts',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 30,
        maxAgeSeconds: 365 * 24 * 60 * 60, // 1 year
      }),
    ],
  })
);
